def packed():
    """The spec exactly as the bridge wants it - base64 of zlib of JSON.

    Handed straight to the add-on without unpacking here: the app has no reason
    to hold half a megabyte of plaintext rig in memory.
    """
    return _PACKED


def asset():
    """The unpacked spec, for the parts the UI needs (labels, defaults, names)."""
    return json.loads(zlib.decompress(base64.b64decode(_PACKED)).decode("utf-8"))
